-- [[ BUTTON CREATOR ]] --
for name, data in pairs(DB) do
    local b = Instance.new("TextButton")
    b.Size = UDim2.new(0.9, 0, 0, 40)
    b.BackgroundColor3 = Color3.fromRGB(25, 25, 30)
    b.Text = name
    b.TextColor3 = Color3.fromRGB(200, 200, 200)
    b.Font = Enum.Font.Code
    b.Parent = sidebar
    Instance.new("UICorner", b)
    
    b.MouseButton1Click:Connect(function()
        currentBox.Text = data
        for _, btn in pairs(sidebar:GetChildren()) do
            if btn:IsA("TextButton") then btn.TextColor3 = Color3.fromRGB(200, 200, 200) end
        end
        b.TextColor3 = Color3.fromRGB(0, 255, 255)
    end)
end

-- [[ TOGGLE BUTTON ]] --
local toggle = Instance.new("TextButton")
toggle.Size = UDim2.new(0, 100, 0, 30)
toggle.Position = UDim2.new(0, 10, 0, 10)
toggle.Text = "BINTZ_V14"
toggle.Parent = gui
toggle.BackgroundColor3 = Color3.fromRGB(15, 15, 25)
toggle.TextColor3 = Color3.fromRGB(0, 255, 255)
toggle.Font = Enum.Font.Code
Instance.new("UIStroke", toggle).Color = Color3.fromRGB(0, 255, 255)

toggle.MouseButton1Click:Connect(function()
    main.Visible = not main.Visible
    toggle.Text = main.Visible and "BINTZ_V14" or "OFF"
end)